"""Source-read petrology questions; retain initial independent discrepancies."""
import json,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[2]/'scripts'))
from common import ROOT,read_csv
by={r['question_id']:r for r in read_csv('data/questions.csv')}
initial={r['question_id']:r for r in json.loads((ROOT/'config/authored_batches/S7_014_independent_answers.json').read_text())}
items=[]
def add(q,stem,values,reasons,answer,solution,core,theories,conditions=None,discipline='geo_petrology',concept='concept_051',ambiguity='',citations=(),verdicts=None):
 r=by[q];assert len(values)==len(reasons)==5
 concept=('soil_origin' if q in ['H25-REG-APPLIED-19','H27-REG-APPLIED-29','R01-RET-APPLIED-28'] else 'accretion_rocks' if q in ['H27-REG-APPLIED-34','R01-RET-APPLIED-31','R05-REG-APPLIED-26'] else 'rock_weathering' if q=='H29-REG-APPLIED-24' else 'igneous_assemblage' if q in ['H27-REG-APPLIED-28','H30-REG-APPLIED-30','R02-REG-APPLIED-25'] else 'pyroclastic_deposit' if q in ['R03-REG-APPLIED-24','R06-REG-APPLIED-26'] else 'metamorphic_equilibrium')
 if verdicts is None:verdicts=['不適切' if i==answer else '適切（一般的分類）' for i in range(1,6)]
 items.append(dict(question_id=q,source_sha256=r['source_sha256'],stem=stem,summary=stem,conditions=conditions or {'方向':'最も不適切なもの。','対象':'一般的な岩石分類・形成過程。'},choices={str(i):dict(value=v,verdict=j,reason=w) for i,(v,j,w) in enumerate(zip(values,verdicts,reasons),1)},figures='原典の問題幹・否定・鉱物名・全5肢を実画像確認。設問固有図なし。',ambiguity=ambiguity,evidence=initial[q]['source_images_viewed'],core_concept=core,required_knowledge=core+'。'+('岩石名と生成過程、鉱物組合せ、温度・圧力・全岩組成、一般則と例外の区別。' if discipline=='geo_petrology' else '母材・運搬堆積・有機物起源、風化、弱面、水の作用、岩盤と土の物性。'),solution=solution,independent_answer=initial[q]['independent_answer'],answer_reason=solution,learning_points=core+'を成因と観察される性質に結び付け、例示と全称命題、主要鉱物と副成分、公式解答と未解決の解釈を区別する。',theory_references=theories,discipline_id=discipline,concept_id=concept,classification_reason='原典全5肢の中心である'+core+'を確認。'+('土の母材・成因又は岩盤の安定性を問うため岩石学から応用地質・地盤へ変更。' if discipline=='geo_engineering' else '岩石の鉱物組合せと形成過程の問題として岩石学に分類。'),calculation='false',figure='false',law='false',evaluation=dict(knowledge_novelty='3',reasoning_steps='2',calculation_load='0',figure_reading='0',difficulty='3',difficulty_reason='物理専攻者に新規の地質用語を形成過程と対応させ、鉱物分類・温度圧力関係・堆積様式を区別する。'),citations=list(citations),foundationality='high',transferability='high'))
def p(*a):return ['theory:petrology:'+x for x in a]
def e(*a):return ['theory:engineering:'+x for x in a]
soil_v=['まさ土の母材は流紋岩である。','しらすは花崗岩の風化物とその二次堆積物である。','黄土は海洋堆積物である。','火山灰質粘性土をレスと呼ぶ。','泥炭はピートとも呼ばれ、未分解の植物組織を肉眼で判定できる。']
soil_r=['まさ土は主に花崗岩類の風化により砂状となった土である。残留と崩積はその後の移動の区別であり、流紋岩を母材とする記述が誤り。','しらすは主に珪長質火砕流の未溶結部などに由来する火山性堆積物で、二次堆積物もある。花崗岩の風化土とは起源が違う。','黄土（レス）は風で運ばれたシルトを主体とする風成堆積物で、海成という説明が誤り。','火山灰由来の粘性土と風成シルトのレスを同一にしない。分布地域が一部重なるだけでは成因を一致させられない。','水分の多い環境などで植物遺体の分解が遅れ、繊維・組織を残す有機質土が泥炭である。分解程度には幅があり、あらゆる泥炭の全組織が必ず肉眼で見えるという一般化は避ける。']
for q,order,ans in [('H25-REG-APPLIED-19',[0,1,2,3,4],5),('H27-REG-APPLIED-29',[0,1,2,3,4],5),('R01-RET-APPLIED-28',[2,1,4,0,3],3)]:
 add(q,'まさ土・しらす・黄土・火山灰質粘性土・泥炭の成因について適切な記述を選ぶ。',[soil_v[i] for i in order],[soil_r[i] for i in order],ans,'色や粒状の見た目だけでなく母材と形成過程を対応させる。まさ土は花崗岩風化、しらすは火山噴出物、黄土は風成シルト、火山灰質粘性土は火山灰の風化等、泥炭は植物遺体の不完全分解である。適切なのは泥炭の'+str(ans)+'である。','特殊土の母材・成因・残存植物組織',e('soil'),conditions={'方向':'最も適切なもの。','対象':'土の一般的な名称と成因。'},discipline='geo_engineering',citations=['mlit_masa','maff_shiras2017','mlit_peat','gsj_loess2002'],verdicts=['適切' if i==ans else '不適切' for i in range(1,6)])
add('H27-REG-APPLIED-28','玄武岩の組成・起源・粘性について不適切な記述を選ぶ。',['富士火山や伊豆大島を構成する苦鉄質火山岩である。','SiO2はおよそ50質量%である。','鉄・マグネシウムの含有量は流紋岩より少ない。','上部マントル岩石の部分溶融が起源の一つである。','流紋岩より粘性が低く、平らな火山体を作りやすい。'],['代表的な玄武岩火山の例である。ただし火山全体の全噴出物を単一岩種と断定しない。','玄武岩の代表的値で、全ての試料を正確に50%とする意味ではない。','玄武岩は流紋岩より一般にFe・Mgに富むので、比較方向が逆。','マントルのかんらん岩が部分溶融して玄武岩質メルトを生じ得る。起源を全溶融と混同しない。','一般に高温でSiO2に乏しい玄武岩質溶岩は流紋岩質より流れやすい。噴火様式・供給量・地形も火山形状へ影響する。'],3,'苦鉄質という分類がFe・Mgに富む組成と対応する。流紋岩はSiO2に富む珪長質岩であり、比較を逆にした3が誤りである。粘性と形状は組成だけでなく温度や結晶量にも依存するため、一般的傾向として読む。','玄武岩質マグマの組成・部分溶融・流動性',p('igneous','magma'),citations=['jma_magma1999','gsj_igneous2021'])
add('H27-REG-APPLIED-34','付加体の構造・弱面と斜面安定性に関する記述を判定する。',['砂岩の岩塊を剥離性の泥質基質が囲むメランジュは表層崩壊等を生じやすい。','片理による結晶片岩の力学的異方性は地盤安定性に影響する。','蛇紋岩には膨張性地山や光沢ある鱗片状剥離面を持ち、地すべりを起こしやすいものがある。','海溝の堆積物は圧縮で形成された衝上断層に沿って大陸側へ付加される。','海溝の大陸側斜面で海底地すべりが起こり、海山が断裂して海溝へ崩壊する。'],['公式はこの肢を不適切とする。しかしメランジュの硬軟混在と割れ目が切土等で問題となることは学会資料で確認できる。深層崩壊との関連もあるが、深層の事例だけで表層崩壊を不可能とは言えない。誤りとする限定根拠は未確定。','面に沿うせん断抵抗などが方向で変わり、弱面と斜面の位置関係を評価する必要がある。等方な単一強度では表せない。','蛇紋岩地域の地すべりや粘土化した蛇紋岩の膨張性地山は一次資料に事例がある。健全な全蛇紋岩が膨潤するとの主張にはしない。','付加は海洋プレート上の堆積物等が剥ぎ取られ、陸側に取り込まれる過程で、衝上断層が発達する。侵食型の沈み込み域もある。','海底斜面崩壊自体は起こり得る。一方、海山は一般に沈み込む海洋プレート上の地形で、この一文の大陸側斜面との関係を疑って初回独立解答5とした。沈み込み中の海山破壊も起こり得るため、単に海山という語だけで絶対的な誤りとは確定しない。'],1,'公式正答は1であり、公式正答表107頁のIII–34の1を画像でも確認した。初回独立解答は5である。原典1の「表層崩壊」と5の「大陸側斜面」「海山」の限定を含め、公式1を支持する排他的理由は現在の一次資料照合では確定していない。メランジュに深層崩壊事例があることだけから1の表層崩壊を誤りとは導かない。相違を未解決として保持し、公式を独立の推論結果と偽らない。','付加体の不均質・異方性・斜面崩壊と未解決の肢解釈',e('accretion','anisotropy'),discipline='geo_engineering',ambiguity='初回独立解答5、公式1。公式表107頁を実画像で再確認。1の表層崩壊を否定する排他的根拠は未確定。5の大陸側斜面と海山の関係も原典のまま保持。メランジュの深層崩壊事例を表層崩壊の不可能性へ読み替えない。Astraで原典と地質機構を重点査読。',citations=['jseg_engineering_faq','kyoto_deep2018','sabo_deep2014','jsce_swelling2010','aist_accretion2026'],verdicts=['公式では不適切／根拠未確定','概ね適切','条件付きで適切','概ね適切','初回独立判断で疑義／未確定'])
add('H29-REG-APPLIED-24','風化・熱水変質・スレーキングが岩石強度へ及ぼす作用を判定する。',['有色鉱物に富む黒い火成岩ほど一般に風化に不安定である。','磁鉄鉱から赤鉄鉱・褐鉄鉱への酸化が風化層の色に現れる。','浸水で間隙空気が圧縮され、岩塊内に圧縮力を生じてスレーキングする。','グリーンタフ地域の新第三紀層は熱水変質で軟弱化していることが多い。','一般に風化・変質は弱化させるが、珪化は強度を増すこともある。'],['高温形成のFe・Mgに富む鉱物は地表環境で変化しやすい。色そのものを原因とする法則ではなく、割れ目や組織も耐風化性を左右する。','Feの酸化と水和等により赤褐色系の鉱物を生じる。褐鉄鉱は単一の理想化学式を持つ一鉱物としてではなく含水酸化鉄の集合の名称として扱う。','空気は圧縮されるが、内圧が孔壁・骨格を押し広げて引張破壊へ働く。空気の圧縮と岩塊への圧縮を混同している。封入空気だけが全試料の機構とも限らない。','火山性の岩石・堆積物が熱水反応で粘土化等を受け、低強度となる場合がある。全てのグリーンタフが同じ弱さという意味ではない。','シリカの充填・交代は緻密化や結合強化をもたらす場合があり、変質=常に強度低下とはしない。'],3,'スレーキングは水への浸漬などで岩塊が崩れる現象である。封入空気モデルでは、水の侵入で圧縮された空気の内圧が骨格を引っ張るので、岩塊の圧縮力とした3が不適切である。空気の状態変化と固体の応力を別々に記述する。膨潤・吸着・化学劣化なども機構となり得る。','風化・変質と間隙内圧による骨格破壊',e('weathering','slaking'),discipline='geo_engineering',citations=['slaking1979','slaking2006','jseg_engineering_faq'])
mineral_v=['花崗岩質岩石は石英・アルカリ長石・斜長石を無色鉱物として含む。','花崗岩質岩石の主な有色鉱物は白雲母・黒雲母・角閃石である。','玄武岩の斑晶には普通輝石・紫蘇輝石・斜長石・かんらん石がある。','安山岩の斑晶には斜長石・普通輝石・紫蘇輝石・角閃石・磁鉄鉱・黒雲母・かんらん石がある。','はんれい岩の主な構成鉱物は普通輝石・斜長石・石英である。']
mineral_r=['珪長質岩の主要な明色鉱物である。ただし鉱物量比が分類を左右し、あらゆる花崗岩類が同量の3種を含むとはしない。','黒雲母・角閃石は代表的な有色鉱物だが、白雲母は通常無色として扱う。白雲母が花崗岩に存在することと、有色分類が正しいことは別であり、原典のまま疑義を残す。','玄武岩の種類により斑晶に現れ得る鉱物群である。全試料に全て同時に存在するという意味には読まない。紫蘇輝石は古い名称で斜方輝石の一種を指す。','安山岩の組成・水分・酸化状態等により現れ得る鉱物群である。かんらん石や黒雲母の存在の可否を、単一の岩種名だけで禁止しない。','一般的なはんれい岩は斜長石・輝石等を主成分とし、石英を典型的主要鉱物に並べる記述が公式の選択対象である。ただし石英はんれい岩という区分はあり、全はんれい岩で石英が絶対にないとはしない。']
for q,order,ans in [('H30-REG-APPLIED-30',[0,1,2,3,4],5),('R02-REG-APPLIED-25',[1,4,0,2,3],2)]:
 v=['原典分類に疑義（通常は白雲母は無色）' if i==1 else '不適切（公式の選択対象）' if i==4 else '適切（鉱物群の例示）' for i in order]
 add(q,'火成岩の主要鉱物・斑晶と有色／無色の区別について不適切な記述を選ぶ。',[mineral_v[i] for i in order],[mineral_r[i] for i in order],ans,'一般的なはんれい岩へ石英を主要鉱物として入れた'+str(ans)+'が公式正答である。一方、原典に白雲母を「有色鉱物」とする記述もある。産総研の結晶構造ギャラリーは白雲母の色を無色と記載しており、初回独立解答は'+initial[q]['independent_answer']+'であった。原典を黒雲母へ直したり白雲母も通常有色と教えたりせず、疑義を保存する。石英はんれい岩の例外も含め、公式の一般的主要鉱物の比較と厳密な分類を分ける。','火成岩の鉱物組合せと有色分類の原典疑義',p('igneous','minerals','exceptions'),ambiguity='原典は花崗岩の主な有色鉱物に白雲母を含める。通常の無色分類と矛盾し、初回独立解答'+initial[q]['independent_answer']+'、公式'+str(ans)+'。白雲母を改変しない。石英はんれい岩の例外と「主な」の範囲を含めAstraで査読。',citations=['aist_crystal_colors','gsj_igneous2021','usgs_rock_thesaurus'],verdicts=v)
add('R01-REG-APPLIED-24','変成岩の形成要因、変成帯、高圧多形について不適切な記述を選ぶ。',['火成岩・堆積岩・変成岩のいずれも原岩となる。','固体中の新鉱物形成と外力による変形が変成作用の要素である。','鉱物組合せは岩石の化学組成によらず温度・圧力のみで決まる。','西南日本の高圧型変成帯は北から蓮華・周防・三波川の順に分布する。','コース石・ダイヤモンドは石英・石墨のそれぞれ高圧多形である。'],['既存の変成岩が再び違う条件を受ける複変成もある。','再結晶・反応と変形を区別する。ただし接触変成などで顕著な変形を必須とはしない。','温度・圧力に加えて全岩組成・流体組成等が必要である。元素が存在しなければその元素を要する鉱物はできない。','原画像では蓮華・周防・三波川でありOCRの進華等を採用しない。高圧帯の典型的配置をいう。','同じ化学組成でも結晶構造が違い、高圧側ではより稠密な構造が安定となる。コース石はSiO2、両炭素鉱物はCである。'],3,'鉱物組合せの平衡は温度・圧力の下で、供給される元素量を制約として自由エネルギーを最小化して決まる。したがって化学組成を無視する3が誤りである。石灰岩と泥岩を同じ温度圧力で変成しても同じ鉱物群になるとは限らない。','変成鉱物組合せの温度・圧力・組成依存と多形',p('metamorphism','equilibrium','paired'),citations=['nelson_assemblages2011','gsj_metamorphic_words','gsj_highpressure2016','hokkaido_polymorph2012'])
for q,order,ans in [('R01-RET-APPLIED-31',['玄武岩','泥岩','チャート','花崗岩','石灰岩'],4),('R05-REG-APPLIED-26',['玄武岩','花崗岩','石灰岩','チャート','泥岩'],2)]:
 reasons={'玄武岩':'海洋地殻・海山などの火山岩が沈み込み時に付加され得る。','泥岩':'海溝などに運ばれる細粒砕屑堆積物が構成物となる。','チャート':'海洋プレート上の遠洋性珪質堆積物として運搬・付加され得る。','花崗岩':'一般に地下の珪長質マグマの結晶化で形成され、海洋プレートの層序を剥ぎ取る付加物の典型ではない。付加後の花崗岩貫入まで否定しない。','石灰岩':'海山上の浅海生物起源の炭酸塩岩などが付加体へ取り込まれ得る。'}
 add(q,'付加体へ取り込まれる典型的な岩石群から、最も関係の薄いものを選ぶ。',order,[reasons[v] for v in order],ans,'海洋プレート本体・海山から玄武岩、遠洋の珪質堆積からチャート、海山上の炭酸塩堆積から石灰岩、海溝等の砕屑堆積から泥岩を対応させる。付加により取り込まれる典型的な岩石ではない花崗岩の'+str(ans)+'を選ぶ。現在の付加体地域に後で貫入した花崗岩が存在することとは両立する。','付加体の海洋プレート起源の岩石群',p('accretion'),conditions={'方向':'付加体の構成岩として最も関係のないもの。','範囲':'典型的な付加構成岩と後の貫入岩を区別。'},citations=['aist_accretion2026','gsj_saganoseki1993'],verdicts=['最も関係が薄い' if i==ans else '構成岩となり得る' for i in range(1,6)])
add('R03-REG-APPLIED-23','泥質変成岩の組織と変成度による岩型名を判定する。',['スレートは剥離性の発達した細粒岩で石材にも使われる。','泥質岩の変成温度上昇に伴いスレート・千枚岩・片岩・片麻岩の順の変化が見られる。','片麻岩は粗粒で片状構造や縞状構造が見られない。','片岩は片理の発達した広域変成岩の総称である。','ホルンフェルスは一般に片理・縞を持たず熱変成で形成される。'],['細粒でもよく割れる劈開を持つ点が特徴で、屋根材などへ加工できる。','泥質の代表的な進行変成系列である。岩型名は組成・変形・組織にも依存し、温度だけの万能温度計ではない。','片麻岩は明暗の鉱物群が作る縞状組織などを持つ。見られないとの否定が誤り。','配向した板状鉱物等が面構造を作る。片理は単純な堆積時の層理とは異なる。','方向性に乏しい緻密な再結晶組織が典型である。原岩の構造が残ることまで絶対に排除しない。'],3,'粒の大きさと面・縞の構造を別々に確認する。片麻岩は粗粒という点だけで識別せず、鉱物の偏在による縞状組織が典型なので、それを否定する3が誤りである。','泥質岩の変成度と片理・片麻状組織',p('textures','metamorphism'),citations=['gsj_metamorphic_words','nelson_regional2011'])
py_v=['多孔質で低い見かけ密度の白〜灰色砕屑物は軽石、暗色のものはスコリアという。','粒径区分は細かい方から火山灰・火山礫・火山岩塊および火山弾である。','アグロメレートは火山灰基質に火山弾・本質岩塊を多く含み火口近くに分布する。','降下軽石は基質支持、火砕流堆積物は岩片支持である。','アグルチネートは放出された高温の岩片が溶結したものである。']
py_r=['発泡したマグマ由来の砕屑物で、色・組成に差がある。低い見かけ密度と鉱物そのものの密度を混同しない。','灰は2 mm未満、火山礫は2〜64 mm、岩塊・火山弾は64 mm超が基準である。岩塊と火山弾は同じ粗粒区分で、主に固結状態・形状で分ける。','火口付近に堆積しやすい大きな本質砕屑物を多く含む火砕岩の説明である。','典型的な降下軽石は比較的淘汰され粒子同士で支持し、火砕流は細粒灰を含む不淘汰な基質支持が一般的であり、比較方向が逆。流れの相や堆積位置による例外はある。','まだ高温で粘着性のある放出物が集積し結合した岩石である。冷たい砕屑物の機械的固結だけとは異なる。']
for q,order,ans in [('R03-REG-APPLIED-24',[0,1,2,3,4],4),('R06-REG-APPLIED-26',[0,1,2,4,3],5)]:
 add(q,'火山砕屑物の名称・粒径・堆積様式・溶結について不適切な記述を選ぶ。',[py_v[i] for i in order],[py_r[i] for i in order],ans,'名称、粒径、支持構造、堆積後の結合を別軸で比較する。降下軽石の比較的よくそろった粒子支持と、火砕流の灰を含む基質支持を入れ替えた'+str(ans)+'が不適切である。火山弾を火山岩塊より必ず大粒とする粒径順序へは読み替えない。','火山砕屑物の粒径・支持構造・溶結',p('pyroclast','deposition'),concept='concept_055',citations=['usgs_tephra_sizes','usgs_pinatubo1996','usgs_ash_density','usgs_bishop_tuff'])
meta_v=['岩石が高い温度・圧力の下で固体のまま鉱物や組織を変えると変成岩になる。','マグマの貫入による周囲の加熱で接触変成岩を生じる。','プレート運動に伴う広範囲の温度・圧力条件で広域変成岩を生じる。','石灰岩が接触変成を受けると大理石となる。','弧–海溝系では海溝側に高温低圧型、陸側の火山前線下に低温高圧型ができる。']
meta_r=['変成は固体状態の反応・再結晶・変形を中心とする。鉱物組成の変化と全岩化学組成の変化を区別し、全岩の外部物質交換を必須とはしない。','局所的な熱源により貫入岩周辺に変成の帯を生じる。','地殻変動や沈み込みにより広い範囲で変成条件が成立する。高温と高圧が常に同じ程度である必要はない。','炭酸塩鉱物の再結晶で大理石となる。広域変成によっても形成され、接触のみという排他的分類ではない。','沈み込む冷たいプレート側は相対的な低温高圧、マグマによる熱源側は高温低圧なので逆である。']
for q,order,ans in [('R05-REG-APPLIED-24',[0,1,2,3,4],5),('R07-REG-APPLIED-23',[0,1,2,4,3],4)]:
 add(q,'固体の変成作用、接触・広域変成、弧–海溝系の温度圧力配置を判定する。',[meta_v[i] for i in order],[meta_r[i] for i in order],ans,'深く沈む比較的冷たいプレートは圧力の上昇に比べ温度上昇が小さい。火山弧下のマグマ近傍は熱源による高温が支配的になる。両側の低温高圧／高温低圧を逆にした'+str(ans)+'が誤りである。大理石は接触でも広域でもできるが、石灰岩の接触変成で形成されるという例示自体は正しい。','変成過程と対の変成帯の熱・圧力の成因',p('metamorphism','paired'),citations=['aist_awa2021','nelson_contact2011','gsj_metamorphic_words'])
add('R06-REG-APPLIED-27','変成作用の定義と領家・三波川の変成型を判定する。',[meta_v[0],meta_v[2],meta_v[1],'領家帯は低温高圧、三波川帯は高温低圧である。','結晶片岩・片麻岩は広域変成岩、ホルンフェルス・大理石は接触変成岩に属する。'],[meta_r[0],meta_r[2],meta_r[1],'領家は高温低圧、三波川は低温高圧の代表であり、対応が逆。','試験では代表的な形成例の対応としているが、大理石は石灰質原岩の広域変成でもできる。全ての大理石を接触起源と断定するなら誤りとなるので、例示と排他的区分を区別する。'],4,'領家はマグマに関連する高温低圧型、三波川は沈み込みに関連する低温高圧型である。逆にした4が公式正答かつ初回独立解答である。ただし5は大理石の広域変成での形成を省いており、全称的な分類として読む場合には追加の疑義がある。原典の断定をそのまま普遍則として教えず、解釈確認を残す。','領家・三波川の変成型と大理石分類の適用範囲',p('paired','exceptions'),ambiguity='初回独立解答4と公式4は一致。5の「大理石は接触変成岩に属する」は代表例としては通用するが広域変成でも大理石が形成される。排他的な全称分類か例示かの読みをAstraで確認。',citations=['aist_awa2021','nelson_regional2011','nelson_contact2011'],verdicts=['適切','適切','適切','不適切','代表例として適切／全称解釈に疑義'])
